def crc_reflected(bits, init=0xFFFFFFFF, poly=0xEDB88320, final=0xFFFFFFFF):
    crc = init
    for b in bits:
        fb = (crc & 1) ^ b
        crc >>= 1
        if fb:
            crc ^= poly
    return (crc ^ final) & 0xFFFFFFFF

def crc_normal_msb(bits_msb_first, init=0xFFFFFFFF, poly=0x04C11DB7, final=0xFFFFFFFF):
    crc = init
    for b in bits_msb_first:
        msb = (crc >> 31) & 1
        crc = ((crc << 1) & 0xFFFFFFFF)
        if msb ^ b:
            crc ^= poly
    return (crc ^ final) & 0xFFFFFFFF

def bits_of(v, order):
    # order: list of bit indices in processing order
    return [(v >> i) & 1 for i in order]

targets = {0:558161692, 1:2768625435, 0x12345678:1242070680, 0xFFFFFFFF:4294967295, 42:3864204343}

orders = {
    'lsb-first (wire0..31)': list(range(32)),
    'msb-first (wire31..0)': list(range(31,-1,-1)),
    'byteLE_msb-first-in-byte': [b*8+(7-k) for b in range(4) for k in range(8)],
    'byteBE_lsb-first': [b*8+k for b in [3,2,1,0] for k in range(8)],
    'byteBE_msb-first': [b*8+(7-k) for b in [3,2,1,0] for k in range(8)],
}
import itertools
for oname, order in orders.items():
    for init in [0xFFFFFFFF, 0]:
        for final in [0xFFFFFFFF, 0]:
            # reflected
            ok = all(crc_reflected(bits_of(v,order),init,0xEDB88320,final)==exp for v,exp in targets.items())
            if ok:
                print(f"MATCH reflected {oname} init={init:#x} final={final:#x}")
            ok2 = all(crc_normal_msb(bits_of(v,order),init,0x04C11DB7,final)==exp for v,exp in targets.items())
            if ok2:
                print(f"MATCH normal {oname} init={init:#x} final={final:#x}")
print("done brute force 1")

